from .lsu import LSU
from .tstm import Tstm
from .airmosaic import Airmosaic, AirmosaicWA


def lookup_node_type(*expected_types):  # noqa: C901
    def with_lookup(func):
        @wraps(func)
        def wrapper(self, *args, **kwargs):
            arg_lst = list(args)
            node = arg_lst[0]

            if _is_string(node):
                instance = self._get_attribute(node)
            else:
                instance = node
            _check_type(instance)

            arg_lst[0] = instance
            new_args = tuple(arg_lst)

            return func(self, *new_args, **kwargs)
        return wrapper

    def _is_string(input):
        if sys.version.startswith('2'):
            return isinstance(input, basestring)  # noqa: F821
        else:
            return isinstance(input, str)

    def _check_type(checked):
        for expected_type in expected_types:
            if isinstance(checked, expected_type):
                break
        else:
            raise NodeTypeMismatch(str(type(checked)) + "|" + str(expected_types))

    return with_lookup


class Prisma(ManagedObject):

    def __init__(self, config, node_dict, **kwargs):
        self.__dict__ = node_dict
        super().__init__(**kwargs)
        self.config = config
        self._add_prerequisites()

    def _add_prerequisites(self):
        for node_name in self.config.prisma.components:
            self.add_prerequisite(self._get_attribute(node_name))

    def _get_attribute(self, node_name):
        try:
            attr = self.__getattribute__(str(node_name))
        except Exception:
            raise AttributeNotFound()
        else:
            return attr

    def _save_file(self, data, file_path):
        if os.path.isfile(file_path):
            os.remove(file_path)

        with open(file_path, 'wb') as target_file:
            target_file.write(data)

    @lookup_node_type(LSU)
    def start_lsu(self, node, timeout):
        return node.start_lsu(timeout=timeout)

    @lookup_node_type(LSU)
    def stop_lsu(self, node, timeout):
        return node.stop_lsu(timeout=timeout)

    @lookup_node_type(LSU)
    def clean_lsu(self, node, timeout):
        return node.clean_lsu(timeout=timeout)

